      "留守的农民夫妇": "Фермерская пара, которая осталась",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "Спокойнее, юноша. Эти медведи не убивали никого здесь. Когда они пришли на ферму, они только отогнали жителей к королевской столице.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "Мы остались, потому что никогда не чувствовали от них враждебности. Сначала они не знали даже, как держать плуг — они просто размешивали поля в беспорядок грубой силой.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "Позже мы научили медведей-самцов чинить каналы и сеять пшеницу, и научили медведей-самок ухаживать за ульями и собирать урожай. Они учатся медленно, но никогда не тратят пищу впустую.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "Они экономят теплое место в амбаре для своих детенышей, и приносят первый мешок новой пшеницы к нашей двери. По крайней мере, в наших глазах, они не такие мерзкие, как говорят слухи.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "Если ты должен идти дальше, посмотри собственными глазами, прежде чем судить. То, что произошло здесь, может быть не простым случаем захвата деревни монстрами.",
      "露珠幼母": "Мать выводка Росинки",
