      "我会把你的战术连同桌子一起劈开": "Я расколю твою тактику пополам вместе со столом",
      "星界学院": "Академия Астральных Знаний",
      "用观测和演算让星象不再只是预言": "Использование наблюдения и расчётов так, чтобы звёзды больше не были только пророчеством",
