      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "Четыре офицеры суккубов отказываются отступать и контратакуют одновременно с атакой 20; отряд будет отброшен, но Глава 5 считается очищенной.",
      "四位魅魔军官没有进攻，只维持结界，为同伴撤离争取两回合。": "Четыре офицеры суккубов не атакуют; они только поддерживают барьер, выигрывая два хода для побега своего товарища.",
      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "Контратака Тысячи Ветвей начинается: четыре офицеры суккубов атакуют отряд один за другим с атакой 20.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "Штурм четырёх офицеров прорывает линию, и авангард демонического альянса пересекает разлом, чтобы захватить руины; отряд вынужден покинуть Город Тысячи Ветвей.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "Четыре офицеры суккубов разбили отряд, но охотница «Серебристо-серый волк» уже была побеждена: история Главы 5 завершена, и все трофеи и награды за очистку выданы как обычно.",
