      "直面狼王": "Встретить Волчьего Короля",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "Глава 5 находится в древних развалинах к югу от Изумрудного города. Серые волки и другие звери быстро расширяют свою территорию и устраивают засады; в конце вы встречаетесь с Охотницей на Серебристых Волков.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "Глава 4 содержит двадцать узлов-боссов с Слизнями. Они имеют высокое Здоровье, низкую Атаку и постоянно регенерируются; следуйте светящемуся потоку глубоко в лес, чтобы встретить Великого Мудреца Нефрии Голубой Росы.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "Глава 3 содержит двадцать узлов-боссов с Медведями и ферму. Следуйте тропам фермы, чтобы исследовать оккупированную деревню, и наконец встретьте Королеву Урожая Брейю.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "Глава 2 содержит двадцать узлов-боссов. Продвигайтесь вдоль оборон армии гоблинов и наконец встретьте Королеву Изумрудной Тени с 200 Здоровьем.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "Разверните свою армию на четырех боевых линиях с передним и задним рядами, пробейте брешь и пройдите тринадцать узлов Туманного леса. Каждая победа становится силой для следующей экспедиции.",
