      "已击败的节点、路线解锁和本轮奖励都会保留。之后点击“继续游戏”即可从当前进度继续。": "Побеждённые узлы, разблокированные маршруты и награды этого забега сохраняются. Нажмите «Продолжить» позже, чтобы возобновить с вашего текущего прогресса.",
