      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "Установит главу 5 так, чтобы первые 19 боссов были побеждены, осталась только Охотница серебристо-серых волков. Ваш герой, золото, коллекция, колода и другие сохранения глав не изменятся.",
