      "第{0}关 · {1}": "Испытание {0} · {1}",
      "有人说{0}永远不可能被人类接纳。可我的军籍、薪饷和选票都是真的。": "Некоторые говорят, что {0} никогда не будет принята людьми. Но моё поступление, мой оклад и мой голос — всё это реально.",
      "记住报名册上的名字——{0}。我来自{1}，也认同人类建立的{2}；所以我选择加入，他们也接受了我。": "Запомните имя в реестре—{0}. Я из {1}, и я верю в {2}, которую люди построили; поэтому я выбрал вступить, и они приняли меня.",
