      "我是{0}，来自{1}。我的研究是{2}；而你，是今天最有价值的实战样本。": "Я {0}, из {1}. Мои исследования — это {2}; и вы сегодняшний самый ценный полевой образец.",
      "我是{0}，来自{1}。我信奉{2}。护卫队长，请用一场完整的战斗回应我。": "Я {0}, из {1}. Я верю в {2}. Капитан стражи, ответьте мне полным боем.",
