      "第{0}节点 · {1}{2}": "Узел {0} · {1}{2}",
      "尚未挑战": "еще не вызван",
      "英雄生命 {0}/{1}，同时恢复满生命": "Здоровье героя {0}/{1}, также полностью восстановлено",
      "会反击": "получает ответный удар",
      "无反击": "нет ответного удара",
      "无法攻击": "не может атаковать",
      "罗兰·维克": "Роланд Вик",
      "前王都护卫队长": "Бывший капитан королевской стражи",
      "莉瑟尔": "Лизель",
      "薇奥菈": "Виола",
      "赛琳娜": "Селина",
      "格罗姆": "Гром",
